<template>
	<view class="membership-page">
		<view class="membership-header" :style="{ paddingTop: statusBarHeight + 'px' }">
			<view class="nav-bar"><view class="back-button" @click="goBack"><text class="back-arrow"></text></view><text class="nav-title">会员中心</text><view class="nav-placeholder"></view></view>
		</view>
		<view :style="{ height: headerHeight + 'px' }"></view>
		<scroll-view class="membership-scroll" scroll-y enhanced :show-scrollbar="false" :style="{ height: scrollHeight + 'px' }">
			<view class="member-card" :class="{ active: summary.isMember }">
				<view class="member-card-head"><text class="member-brand">TIME CAPSULE</text><view class="member-status">{{ summary.isMember ? 'ACTIVE' : 'GUEST' }}</view></view>
				<view class="member-chip"><view class="chip-line"></view><view class="chip-line"></view></view>
				<text class="member-card-title">{{ summary.isMember ? getPlanName(summary.planType) : '轻享会员' }}</text>
				<text class="member-card-number">MEMBER · {{ summary.isMember ? 'PREMIUM' : 'NOT ACTIVATED' }}</text>
				<view class="member-card-foot"><view><text class="card-label">会员状态</text><text class="card-value">{{ summary.isMember ? '已开通' : '未开通' }}</text></view><view><text class="card-label">有效期至</text><text class="card-value">{{ summary.isMember ? formatDate(summary.expiresAt) : '----.--.--' }}</text></view></view>
			</view>
			<view class="plans-section">
				<text class="plans-title">会员套餐</text>
				<view class="plan-grid">
					<view v-for="plan in summary.plans" :key="plan.type" class="plan-card" :class="{ selected: selectedPlanType === plan.type }" @click="selectedPlanType = plan.type">
						<view v-if="selectedPlanType === plan.type" class="selected-badge"><text class="selected-check">✓</text><text>已选择</text></view>
						<view v-if="plan.recommended || (hasDiscount(plan) && plan.discountLabel)" class="plan-tags">
							<view v-if="plan.recommended" class="recommend-tag">推荐</view>
							<view v-if="hasDiscount(plan) && plan.discountLabel" class="discount-tag">{{ plan.discountLabel }}</view>
						</view>
						<text class="plan-name">{{ plan.name }}</text>
						<text class="plan-price">¥ {{ formatPrice(plan.price) }}</text>
						<text class="plan-original" :class="{ 'is-hidden': !hasDiscount(plan) }">¥ {{ getOriginalPrice(plan) }}</text>
						<text class="plan-bonus" :class="{ 'is-hidden': !hasBonusDiamonds(plan) }">加赠 {{ Number(plan.bonusDiamonds || 0) }} 钻</text>
						<view class="plan-divider"></view>
						<text class="plan-selling">{{ getPlanSelling(plan) }}</text>
						<text class="plan-duration">尊享会员权限{{ plan.days }}天</text>
					</view>
				</view>
			</view>
			<view v-if="!summary.isMember" class="checkin-promo" @click="focusPlan('quarterly')">
				<view class="checkin-promo-tag">会员独享 · 限时</view>
				<view class="checkin-promo-main">
					<text class="checkin-promo-title">每日签到 立得 <text class="checkin-promo-amount">60</text> 钻石</text>
					<text class="checkin-promo-sub">开通会员后每天签到直接到账 60 钻石，持续积累更多互动机会。</text>
				</view>
				<view class="checkin-promo-arrow">›</view>
			</view>

			<view class="privilege-panel">
				<view class="privilege-heading"><view class="heading-line"></view><text>{{ summary.isMember ? '会员专属权益' : '轻享会员可解锁9项权益' }}</text><view class="heading-line"></view></view>
				<view class="benefit-grid">
					<view v-for="benefit in displayBenefits" :key="benefit.code" class="benefit-item" :class="{ 'is-hot': benefit.hot }">
						<view v-if="benefit.hot" class="hot-badge">HOT</view>
						<view class="benefit-icon"><text>{{ benefit.icon }}</text></view>
						<text class="benefit-name">{{ benefit.title }}</text>
					</view>
				</view>
			</view>
			<view class="content-bottom-space"></view>
		</scroll-view>
		<view class="payment-bar">
			<view class="pay-button" :class="{ disabled: !selectedPlan }" @click="paySelectedPlan"><text>立即支付</text><text v-if="selectedPlan"> · ¥{{ formatPrice(selectedPlan.price) }}</text></view>
			<text class="agreement-note">点击支付即代表同意<text class="agreement-link" @click.stop="goAgreement">《充值协议》</text></text>
	</view>
	</view>
</template>

<script>
import { fetchMembership, createMembershipOrder } from '../../api/membership';
import { showRequestError } from '../../utils/feedback';

export default {
	data() { return { statusBarHeight: 44, headerHeight: 100, scrollHeight: 600, selectedPlanType: 'quarterly', summary: { isMember: false, expiresAt: '', plans: [], benefits: [] } }; },
	computed: {
		selectedPlan() { return this.summary.plans.find((plan) => plan.type === this.selectedPlanType) || null; },
		displayBenefits() {
			return [
				{ code: 'member_badge', title: '会员标识', icon: '♛' },
				{ code: 'unlimited_chat', title: '无限畅聊', icon: '∞' },
				{ code: 'member_gift', title: '专属礼物', icon: '礼' },
				{ code: 'super_exposure', title: '超级曝光', icon: '•••' },
				{ code: 'profile_decoration', title: '更多装扮', icon: 'V' },
				{ code: 'diamond_gift', title: '钻石礼包', icon: '◆' },
				{ code: 'avatar_frame', title: '专属头像框', icon: '框' },
				{ code: 'diamond_recharge_double', title: '充值双倍', icon: '2X', hot: true },
				{ code: 'daily_checkin', title: '每日领60钻', icon: '签', hot: true }
			];
		}
	},
	onLoad() {
		const info = uni.getSystemInfoSync();
		const rpxToPx = Number(info.windowWidth || 375) / 750;
		this.statusBarHeight = info.statusBarHeight || 44;
		this.headerHeight = this.statusBarHeight + Math.round(92 * rpxToPx);
		this.scrollHeight = Math.max(320, Number(info.windowHeight || 700) - this.headerHeight);
		this.loadData();
	},
	methods: {
		async loadData() { try { this.summary = await fetchMembership(); } catch (error) { showRequestError(error, '会员信息加载失败'); } },
		async paySelectedPlan() {
			if (!this.selectedPlan) return;
			try {
				const order = await createMembershipOrder(this.selectedPlan.type);
				if (!order || !order.payment) {
					throw new Error('支付参数未返回，请检查线上后端支付配置和服务是否已重启。');
				}
				if (!uni.requestPayment) {
					throw new Error('当前预览环境不支持微信支付，请使用微信小程序真机调试。');
				}
				await new Promise((resolve, reject) => {
					uni.requestPayment({ ...order.payment, success: resolve, fail: reject });
				});
				uni.showToast({ title: this.hasBonusDiamonds(this.selectedPlan) ? '会员和赠钻即将到账' : '支付成功，会员即将生效', icon: 'success' });
				setTimeout(() => this.loadData(), 1200);
			} catch (error) {
				if (error && (error.errMsg || '').includes('cancel')) return;
				showRequestError(error, '会员支付失败');
			}
		},
		formatPrice(value) { return Number(value || 0).toFixed(2); },
		getOriginalPriceValue(plan) {
			const configured = Number(plan && plan.originalPrice);
			if (Number.isFinite(configured) && configured > 0) return configured;
			return Number(({ monthly: 19.9, quarterly: 59.9, yearly: 159.9 })[plan.type] || plan.price || 0);
		},
		getOriginalPrice(plan) { return this.formatPrice(this.getOriginalPriceValue(plan)); },
		hasDiscount(plan) { return this.getOriginalPriceValue(plan) > Number(plan && plan.price || 0); },
		hasBonusDiamonds(plan) { return Boolean(plan && plan.bonusDiamondsEnabled && Number(plan.bonusDiamonds || 0) > 0); },
		getPlanSelling(plan) { return plan.label || ({ monthly: '随时体验', quarterly: '人气之选', yearly: '长期最省' })[plan.type] || '尊享权益'; },
		getPlanName(type) { return ({ monthly: '月度会员', quarterly: '季度会员', yearly: '年度会员' })[type] || '轻享会员'; },
		formatDate(value) { const date = new Date(value); return Number.isNaN(date.getTime()) ? '' : `${date.getFullYear()}.${String(date.getMonth() + 1).padStart(2, '0')}.${String(date.getDate()).padStart(2, '0')}`; },
		goAgreement() { uni.navigateTo({ url: '/pages/membership/agreement' }); },
		goBack() { uni.navigateBack(); },
		focusPlan(type) {
			if (!type) return;
			this.selectedPlanType = type;
			uni.showToast({ title: '已为你推荐季度会员', icon: 'none' });
		}
	}
};
</script>

