.plan-card { position: relative; display: flex; flex-direction: column; align-items: center; min-width: 0; min-height: 354rpx; padding: 30rpx 8rpx 22rpx; border: 3rpx solid rgba(255,255,255,.08); border-radius: 14rpx; background: #ffedd8; color: #171514; opacity: .76; filter: saturate(.72); box-sizing: border-box; transform: scale(.97); transition: transform .16s ease, border-color .16s ease, opacity .16s ease; }
