.plan-card.selected { z-index: 2; border: 6rpx solid #d9972f; opacity: 1; filter: none; box-shadow: 0 0 0 4rpx rgba(255,215,132,.32), 0 18rpx 38rpx rgba(211,143,37,.32), inset 0 1rpx 0 rgba(255,255,255,.55); transform: translateY(-9rpx) scale(1.025); }
.selected-badge { position: absolute; left: 50%; top: -22rpx; display: flex; align-items: center; gap: 5rpx; height: 38rpx; padding: 0 15rpx; border: 2rpx solid #f6d995; border-radius: 19rpx; background: #a66b18; color: #fff3d1; font-size: 18rpx; white-space: nowrap; transform: translateX(-50%); box-shadow: 0 5rpx 12rpx rgba(91,52,7,.3); box-sizing: border-box; }
.selected-check { font-size: 20rpx; font-weight: 700; }
.plan-name { font-size: 32rpx; font-weight: 700; }
.plan-price { margin-top: 22rpx; font-size: 43rpx; font-weight: 500; white-space: nowrap; }
.plan-original { margin-top: 10rpx; color: #574a3d; font-size: 24rpx; text-decoration: line-through; }
.plan-original.is-hidden, .plan-bonus.is-hidden { visibility: hidden; }
.plan-bonus { min-height: 28rpx; margin-top: 8rpx; color: #c43d32; font-size: 19rpx; font-weight: 700; line-height: 28rpx; }
