.pay-button { display: flex; align-items: center; justify-content: center; height: 88rpx; margin: 0; border-radius: 18rpx; background: linear-gradient(90deg, #fff5e7, #ffc980); color: #594326; font-size: 31rpx; box-shadow: 0 10rpx 28rpx rgba(196,138,61,.18); }
